import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { defineConfig, type Plugin } from 'vite';
import react from '@vitejs/plugin-react';
import tailwindcss from '@tailwindcss/vite';

/**
 * The `stacktape` package's type declarations, which the TypeScript editor checks `stacktape.ts` against: the same
 * files the npm package publishes and the docs' Twoslash reads, generated by the CLI's `generate:monaco` (Turbo runs it
 * before this build). Served from the bundle as `stacktape-types/*.d.ts`; a missing file fails the build.
 */
const STACKTAPE_DECLARATIONS = ['index.d.ts', 'types.d.ts', 'plain.d.ts', 'cloudformation.d.ts'] as const;
const declarationsDirectory = fileURLToPath(new URL('../cli/.generated/monaco-declarations/', import.meta.url));
const readDeclaration = (name: string) =>
  readFile(`${declarationsDirectory}${name}`).catch(() => {
    throw new Error(
      `Missing ${declarationsDirectory}${name}. Run \`pnpm exec turbo run generate:monaco --filter @stacktape/cli\`.`
    );
  });

const stacktapeTypes = (): Plugin => ({
  name: 'stacktape-types',
  configureServer(server) {
    server.middlewares.use((request, response, next) => {
      const name = /^\/stacktape-types\/([\w.]+)$/.exec(request.url ?? '')?.[1];
      if (name === undefined || !(STACKTAPE_DECLARATIONS as readonly string[]).includes(name)) return next();
      void (async () => {
        try {
          const contents = await readDeclaration(name);
          response.setHeader('content-type', 'text/plain; charset=utf-8');
          response.end(contents);
        } catch (error) {
          next(error);
        }
      })();
    });
  },
  async generateBundle() {
    const sources = await Promise.all(STACKTAPE_DECLARATIONS.map(readDeclaration));
    STACKTAPE_DECLARATIONS.forEach((name, index) =>
      this.emitFile({ type: 'asset', fileName: `stacktape-types/${name}`, source: sources[index]! })
    );
  }
});

/**
 * The wizard is embedded in the CLI, not hosted.
 *
 * That decides most of this file. Assets are referenced relatively because the page is served from a
 * localhost origin whose port changes every run; nothing is split into async chunks the browser
 * would have to fetch separately, because the whole point is that it works offline and on a locked
 * down network; and the output lands where the CLI build copies it from.
 */
export default defineConfig({
  plugins: [react(), tailwindcss(), stacktapeTypes()],
  base: './',
  resolve: {
    // `@stacktape/ui-react` is consumed as source and declares React as a peer, so without this the
    // bundle can end up with two copies — and a hook called against the second one finds a null
    // dispatcher, which surfaces as "Cannot read properties of null (reading 'useRef')".
    dedupe: ['react', 'react-dom'],
    alias: {
      // Monaco's files by their path inside the package, for the lean entry in `src/editor/monaco-lean.ts`. The
      // package's export map cannot reach its stylesheets.
      'monaco-esm': fileURLToPath(new URL('./node_modules/monaco-editor/esm/vs', import.meta.url)),
      // monaco-worker-manager (under monaco-yaml) still imports Monaco's pre-0.56 worker path; 0.56 exports the same
      // worker under this shorter subpath. The Console's build has the same alias.
      'monaco-editor/esm/vs/editor/editor.worker.js': 'monaco-editor/editor/editor.worker.js'
    }
  },
  // Monaco's workers are ES modules; they are files in the bundle, served by the CLI like the page.
  worker: { format: 'es' },
  build: {
    outDir: 'dist',
    emptyOutDir: true,
    // A handful of files rather than a graph of them: this bundle is read off local disk over
    // loopback, so there is nothing to gain from splitting it and a strict CSP to satisfy.
    assetsInlineLimit: 8192,
    rollupOptions: {
      output: {
        entryFileNames: 'assets/[name].js',
        chunkFileNames: 'assets/[name].js',
        assetFileNames: 'assets/[name][extname]'
      }
    }
  }
});
